nodes={}; edges=[]
def cid(s): return 'dayz_'+re.sub(r'[^a-z0-9]+','_',s.lower()).strip('_')
def node(label,f,heading,kind='rationale',rationale=None):
    k=cid(label)
    if k not in nodes:
        nodes[k]=dict(id=k,label=label,file_type=kind,source_file=f,source_location=heading,source_url=None,captured_at=None,author=None,contributor=None)
    if rationale: nodes[k]['rationale']=rationale
    return k
def edge(a,b,f,h,relation='references',confidence='EXTRACTED',score=1.0,detail=None):
    d=dict(source=a,target=b,relation=relation,confidence=confidence,confidence_score=score,source_file=f,source_location=h,weight=1.0)
    if detail:d['description']=detail
    edges.append(d)
