for p,(title,concepts,h,rels) in zip(files,specs):
    f=p.relative_to(root).as_posix(); did='doc_'+re.sub(r'[^a-z0-9]+','_',f.lower()).strip('_')
    nodes[did]=dict(id=did,label=title,file_type='document',source_file=f,source_location='# '+title,source_url=None,captured_at=None,author=None,contributor=None)
    for c in concepts.split('|'):edge(did,node(c,f,h),f,h)
    for a,b,r,d in rels:
        edge(node(a,f,h),node(b,f,h),f,h,r,detail=d)
